SELECT 
FROM bounty_task
WHERE deleted_flag = 0

    AND type = #{type}


    AND status = #{status}

ORDER BY id DESC

SELECT FROM bounty_task WHERE deleted_flag = 0 AND type = 'idea' AND title LIKE CONCAT('%', #{keyword}, '%')
AND id != #{excludeId}
ORDER BY id DESC LIMIT 5

SELECT FROM bounty_task WHERE deleted_flag = 0 AND type = 'idea' AND (
title LIKE CONCAT('%', #{kw}, '%')
)
AND id != #{excludeId}
ORDER BY id DESC LIMIT 5
